2	2	Límites de Consistencia	2025-09-22 15:49:04.385694	{"groups": [{"title": "Límites de Atterberg", "fields": [{"name": "limiteLiquido", "label": "Límite Líquido (LL)", "digits": 2}, {"name": "limitePlastico", "label": "Límite Plástico (LP)", "digits": 2}, {"name": "indicePlasticidad", "label": "Índice de Plasticidad (IP)", "digits": 2}]}]}	{"limite_liquido": {"rows": [{"id": 1, "label": "Ensayo 1"}, {"id": 2, "label": "Ensayo 2"}, {"id": 3, "label": "Ensayo 3"}], "headers": [{"key": "num_golpes", "type": "input", "label": "N° Golpes", "input_config": {"name": "num_golpes"}}, {"key": "codigo", "type": "input", "label": "Código", "input_config": {"name": "codigo"}}, {"key": "tara", "type": "input", "label": "Peso recip. (g)", "input_config": {"name": "tara"}}, {"key": "psht", "type": "input", "label": "Recip. + húmedo (g)", "input_config": {"name": "psht"}}, {"key": "psst", "type": "input", "label": "Recip. + seco (g)", "input_config": {"name": "psst"}}, {"key": "humedad", "type": "calculated", "label": "Humedad (%)", "result_config": {"key": "humedad"}}], "transposed": true, "transposed_header_label": "Propiedad"}, "limite_plastico": {"rows": [{"id": 1, "label": "Ensayo 1"}, {"id": 2, "label": "Ensayo 2"}], "headers": [{"key": "codigo", "type": "input", "label": "Código", "input_config": {"name": "codigo_plast"}}, {"key": "tara", "type": "input", "label": "Peso recip. (g)", "input_config": {"name": "tara_plast"}}, {"key": "psht", "type": "input", "label": "Recip. + húmedo (g)", "input_config": {"name": "psht_plast"}}, {"key": "psst", "type": "input", "label": "Recip. + seco (g)", "input_config": {"name": "psst_plast"}}, {"key": "humedad", "type": "calculated", "label": "Humedad (%)", "result_config": {"key": "humedad_plast"}}], "transposed": true, "transposed_header_label": "Propiedad"}}	{"steps": [{"loop": {"steps": [{"output": "results.limites.humedad.${item.id}", "formula": "(get(data.datos_formulario.TablaLimiteLiquido.psst, item.id, 0) - get(data.datos_formula